  id: "OS-MEM-0470",
  subject: "Operating System",
  subtopic: "Memory Management & Virtual Memory",
  question: "What is the effective memory access time if TLB hit rate is 80%, TLB access = 10ns, memory access = 100ns?",
  options: ["120 ns", "190 ns", "130 ns", "उपयुक्त में से एक से अधिक / More than one of the above", "उपयुक्त में से कोई नहीं / None of the above"],
  answer: "130 ns",
  explanation: "Effective Access Time = (Hit Rate * (TLB + Memory)) + (Miss Rate * (TLB + 2 * Memory)) = 0.8*(10+100) + 0.2*(10+200) = 88 + 42 = 130 ns."
